$codesDir = "scripts/codes"

function Write-Template($id, $title, $desc, $cat, $stars, $author, $views, $updated, $html) {
  $html = $html.Replace('__DLR__', '$')
  $meta = "$id|$title|$desc|$cat|$stars|$author|$views|$updated"
  $b64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($html))
  Set-Content -Path "$codesDir/$id.txt" -Value ($meta + "
" + $b64) -NoNewline
  Write-Host "  $id ($($html.Length) chars)"
}
Write-Template 'crm-dashboard' 'CRM Pipeline' 'CRM pipeline with Kanban deal stages, searchable leads table, and deal value bar chart.' 'Dashboards' 182 'Sarah Chen' '4.2k' '2 days ago' @"<!DOCTYPE html><html lang=en><head><meta charset=UTF-8><meta name=viewport content=""width=device-width,initial-scale=1.0""><title>CRM Pipeline</title><style>body{margin:0;background:#0f172a;color:#e2e8f0;font-family:system-ui,sans-serif}.c{max-width:1200px;margin:0 auto;padding:20px}.h{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.h h1{font-size:24px;margin:0;color:#3b82f6}.s{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.sc{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:20px}.sc h3{color:#64748b;font-size:12px;text-transform:uppercase;margin:0 0 8px;letter-spacing:1px}.sc .v{font-size:32px;font-weight:700;color:#3b82f6}.sc .v.g{color:#22c55e}.kb{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px}.cl{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:16px;min-height:180px}.cl h2{font-size:13px;color:#64748b;text-transform:uppercase;margin:0 0 12px}.ld{background:#0f172a;border:1px solid #334155;border-radius:8px;padding:12px;margin-bottom:8px;cursor:pointer;transition:.2s}.ld:hover{border-color:#3b82f6}.ld h4{font-size:14px;margin:0 0 4px}.ld p{font-size:12px;color:#64748b;margin:0}.ld .a{font-size:13px;font-weight:600;color:#22c55e;margin-top:6px}.sb{margin-bottom:16px}.sb input{width:100%;padding:10px 16px;background:#0f172a;border:1px solid #334155;border-radius:8px;color:#e2e8f0;font-size:14px;outline:none;box-sizing:border-box}.sb input:focus{border-color:#3b82f6}.tw{background:#1e293b;border:1px solid #334155;border-radius:12px;padding:16px;overflow-x:auto}.tw table{width:100%;border-collapse:collapse}.tw th,.tw td{text-align:left;padding:10px 12px;font-size:13px;border-bottom:1px solid #334155;white-space:nowrap}.tw th{color:#64748b;font-size:11px;text-transform:uppercase}.bd{border-radius:4px;padding:2px 8px;font-size:11px;font-weight:600}.bd.wn{background:#22c55e22;color:#22c55e}.bd.ls{background:#ef444422;color:#ef4444}.bd.pd{background:#f59e0b22;color:#f59e0b}.bd.nw{background:#3b82f622;color:#3b82f6}canvas{width:100%!important;height:160px!important;margin-top:12px;border-radius:8px;background:#0f172a}@media(max-width:768px){.kb{grid-template-columns:1fr}.s{grid-template-columns:1fr}}</style></head><body><div class=c><div class=h><h1>CRM Pipeline</h1><span style=color:#64748b;font-size:14px>Alex K.</span></div><div class=s><div class=sc><h3>Total Deals</h3><div class=v id=td>24</div></div><div class=sc><h3>Pipeline Value</h3><div class=v id=pv>__DLR__184.5K</div></div><div class=sc><h3>Win Rate</h3><div class=""v g"" id=wr>68%</div></div></div><div class=sb><input type=text id=si placeholder=""Search leads...""></div><div class=kb id=kb><div class=cl data-st=new><h2>New (3)</h2><div class=ld draggable=true data-v=12000><h4>Acme Corp</h4><p>John D. - john@acme.com</p><div class=a>__DLR__12K</div></div><div class=ld draggable=true data-v=8500><h4>TechStart</h4><p>Sarah K.</p><div class=a>__DLR__8.5K</div></div><div class=ld draggable=true data-v=25000><h4>GlobalSys</h4><p>Mike R.</p><div class=a>__DLR__25K</div></div></div><div class=cl data-st=ql><h2>Qualified (2)</h2><div class=ld draggable=true data-v=45000><h4>DataFlow</h4><p>Emma L.</p><div class=a>__DLR__45K</div></div><div class=ld draggable=true data-v=32000><div class=a>__DLR__32K</div><h4>CloudNine</h4><p>Tom B.</p></div></div><div class=cl data-st=wn><h2>Closed Won (1)</h2><div class=ld draggable=true data-v=62000><h4>NexGen Corp</h4><p>Lisa M.</p><div class=a>__DLR__62K</div></div></div></div><div class=tw><canvas id=dc></canvas><table><thead><tr><th>Lead</th><th>Value</th><th>Stage</th><th>Status</th></tr></thead><tbody id=lb><tr><td>Acme Corp</td><td>__DLR__12K</td><td>New</td><td><span class=""bd nw"">New</span></td></tr><tr><td>TechStart</td><td>__DLR__8.5K</td><td>New</td><td><span class=""bd nw"">New</span></td></tr><tr><td>GlobalSys</td><td>__DLR__25K</td><td>New</td><td><span class=""bd nw"">New</span></td></tr><tr><td>DataFlow</td><td>__DLR__45K</td><td>Qualified</td><td><span class=""bd pd"">Pending</span></td></tr><tr><td>CloudNine</td><td>__DLR__32K</td><td>Qualified</td><td><span class=""bd pd"">Pending</span></td></tr><tr><td>NexGen Corp</td><td>__DLR__62K</td><td>Closed</td><td><span class=""bd wn"">Won</span></td></tr></tbody></table></div></div><script>document.querySelectorAll('.cl').forEach(function(c){c.addEventListener('dragover',function(e){e.preventDefault()});c.addEventListener('drop',function(e){e.preventDefault();var d=e.dataTransfer.getData('text').split(':');var sc=document.querySelectorAll('.cl')[+d[0]];var el=sc.children[+d[1]+1];if(el&&el.classList.contains('ld')){c.appendChild(el);upd();dc()}})});document.querySelectorAll('.ld').forEach(function(l){l.addEventListener('dragstart',function(e){e.dataTransfer.setData('text',Array.from(l.parentElement.parentElement.children).indexOf(l.parentElement)+':'+Array.from(l.parentElement.children).indexOf(l))})});function upd(){document.querySelectorAll('.cl').forEach(function(c){var n=c.querySelectorAll('.ld').length;c.querySelector('h2').textContent=c.querySelector('h2').textContent.replace(/\(\d+\)/,'('+n+')')});var t=0;document.querySelectorAll('.ld').forEach(function(l){t+=+l.dataset.v});document.getElementById('pv').textContent='__DLR__'+(t/1000).toFixed(1)+'K'}function dc(){var c=document.getElementById('dc').getContext('2d');var r=c.canvas.parentElement.getBoundingClientRect();c.canvas.width=r.width-32;c.canvas.height=160;c.clearRect(0,0,c.canvas.width,160);var v=[];document.querySelectorAll('.cl[data-st=wn] .ld').forEach(function(l){v.push(+l.dataset.v)});document.querySelectorAll('.cl[data-st=ql] .ld').forEach(function(l){v.push(+l.dataset.v)});document.querySelectorAll('.cl[data-st=new] .ld').forEach(function(l){v.push(+l.dataset.v)});if(!v.length)return;var mx=Math.max.apply(null,v),w=c.canvas.width-40,bw=Math.max(20,Math.min(50,(w/v.length)-6));c.fillStyle='#1e293b';c.fillRect(0,0,c.canvas.width,160);v.forEach(function(v,i){var h=v/mx*130,x=20+i*(bw+6);c.fillStyle='#3b82f6';c.beginPath();c.roundRect(x,150-h,bw,h,4);c.fill()});c.fillStyle='#64748b';c.font='10px sans-serif';v.forEach(function(v,i){c.fillText('__DLR__'+(v/1000).toFixed(0)+'k',20+i*(bw+6),145-(v/mx*130)-4)})}dc();upd();document.getElementById('si').addEventListener('input',function(){var q=this.value.toLowerCase();document.querySelectorAll('#lb tr').forEach(function(r){r.style.display=r.cells[0].textContent.toLowerCase().includes(q)?'':'none'})})</script></body></html>
"@
